+
+  // Transitional, to be deprecated: only consulted when the engine runs its own
+  // reasoning parser and the structured-output constraint covers only the
+  // output after reasoning. Prefer a constraint that covers the full output
+  // from the first generated token.
+  EngineReasoningGate engine_reasoning_gate = 18;
+}
+
+// Inputs to the engine's reasoning gate, which keeps a structured-output
+// constraint inactive until the engine's reasoning parser detects the end of
+// reasoning.
+message EngineReasoningGate {
+  // Omitted: the engine infers the initial state from the prompt.
+  // true: apply the constraint from the first generated token.
+  // false: generation starts inside reasoning.
+  optional bool reasoning_ended = 1;
+  // Chat template kwargs used to render the prompt, so the engine's reasoning
+  // parser observes the same thinking mode.
+  google.protobuf.Struct chat_template_kwargs = 2;
 }

